INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "刘继勋", "aliases": ["劉繼勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "汲县人，曾任淄州刺史。938年受石敬瑭派遣，将澶州迁到跨德胜津的位置，并迁移顿丘。生卒年未载。", "biography": null, "status": "draft", "id": "fd3230f3-a204-58a2-96b7-0e7419ac3864"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "王廷胤", "aliases": ["王庭胤", "王庭允"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王处存的孙子，曾任贝州防御使。938年任彰德军节度使。《旧五代史》传记作王庭胤，记他字绍基，祖籍长安；同一传记及任官纪事又作王庭允。", "biography": null, "status": "draft", "id": "84bebd8d-f76c-5a88-8a58-3932dce9cb0c"}, {"name": "王周", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷262天复元年条所见人物：王周。", "biography": null, "status": "draft", "id": "dcf3a493-1cbc-5185-9787-8041333d1d90"}, {"name": "王处存", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：王处存。", "biography": null, "status": "draft", "id": "8eb58bbe-206e-5b69-af3c-0dd5435bf54b"}, {"name": "范延光", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：范延光。", "biography": null, "status": "draft", "id": "6889e460-4b23-5243-9441-b5c3a78da98f"}, {"name": "王景（后晋耀州团练使）", "aliases": ["王景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "掖县人，曾任相州刺史。范延光叛乱时，他拒绝服从范延光。938年任耀州团练使。生卒年未载。", "biography": null, "status": "draft", "id": "95c5e667-cc89-51aa-862e-471795aa6956"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "杨溥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明五年条所见人物：杨溥。", "biography": null, "status": "draft", "id": "c9c313a8-8feb-5442-a006-67b9f78d476b"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "李继曮", "aliases": ["李繼曮", "李继严", "李繼嚴", "李从曮", "李從曮", "李从严", "李從嚴"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷273同光二年条所见人物：李继曮。", "biography": null, "status": "draft", "id": "bc5b776d-9d3a-5767-b334-41720016d9eb"}, {"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "桑维翰建议拆分天雄军兵力，以限制杨光远", "start_year": 938, "end_year": 938, "time_original": "938年十一月条下，具体日期未载", "dynasty": "五代十国", "description": "石敬瑭担忧天雄节度使杨光远跋扈、难以控制。桑维翰建议拆分天雄军的兵力。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5ab04800-33ca-529b-9926-0af321549d59"}, {"title": "石敬瑭加杨光远太尉，任西京留守兼河阳节度使", "start_year": 938, "end_year": 938, "time_original": "938年十一月条下，具体日期未载", "dynasty": "五代十国", "description": "石敬瑭加杨光远太尉，任西京留守兼河阳节度使。", "phases": [], "location_name": "西京、河阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "83bc5bfa-5ac5-5073-ae11-1712e112329b"}, {"title": "杨光远因调任不满，私下送礼向契丹申诉", "start_year": null, "end_year": null, "time_original": "调任西京之后，具体年月未载", "dynasty": "五代十国", "description": "杨光远因调任不满，私下送礼向契丹申诉。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2ee1a954-82c2-54a6-ae29-5e9c0b4b3ad3"}, {"title": "史书记述杨光远养私兵千余人，并有异志", "start_year": null, "end_year": null, "time_original": "调任西京后的追述，具体起止年月未载", "dynasty": "五代十国", "description": "《资治通鉴》记杨光远养私兵一千多人，并一直怀有异志。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f658ba55-db1b-5cb6-91d2-0b532054410f"}, {"title": "石敬瑭在广晋府设置邺都", "start_year": 938, "end_year": 938